   127|// ---------- Auto-decomposition ----------
   128|
   129|const DOMAIN_HINTS: Array<{ agent: AgentId; tokens: string[]; label: string }> = [
   130|  { agent: 'backend_developer', tokens: ['backend', 'api', 'hono', 'endpoint', 'server'], label: 'backend changes' },
   131|  { agent: 'frontend_developer', tokens: ['frontend', 'expo', 'react', 'ui', 'screen', 'component'], label: 'frontend changes' },
   132|  { agent: 'infrastructure_sre', tokens: ['render', 'deploy', 'aws', 'dns', 'rollback', 'sre', 'infrastructure'], label: 'infrastructure work' },
   133|  { agent: 'supabase_database', tokens: ['supabase', 'sql', 'rls', 'pgvector', 'schema', 'migration', 'database'], label: 'supabase work' },
   134|  { agent: 'analytics', tokens: ['analytics', 'metrics', 'kpi', 'telemetry', 'dashboard'], label: 'analytics work' },
   135|  { agent: 'operations', tokens: ['ops', 'incident', 'runbook', 'triage', 'owner comm'], label: 'operations triage' },
