   138|export function autoDecomposeGoal(goal: string): ChildTaskSpec[] {
   139|  const lower = goal.toLowerCase();
   140|  const matched = DOMAIN_HINTS.filter((h) => h.tokens.some((t) => lower.includes(t)));
   141|  const picked = matched.length >= 2 ? matched : DOMAIN_HINTS.slice(0, 3);
   142|  return picked.map((h, idx) => ({
   143|    ref: `child_${idx + 1}_${h.agent}`,
   144|    goal: `${h.label} for parent goal: ${goal}`,
   145|    forceAgent: h.agent,
   146|  }));
