   149|// ---------- Validation of specs ----------
   150|
   151|function validateChildSpecs(specs: ChildTaskSpec[]): void {
   152|  if (specs.length < 2) throw new Error('parent task must have at least 2 children.');
   153|  const refs = new Set<string>();
   154|  for (const c of specs) {
   155|    if (!c.ref || typeof c.ref !== 'string') throw new Error('child.ref is required.');
   156|    if (refs.has(c.ref)) throw new Error(`duplicate child ref: ${c.ref}`);
   157|    refs.add(c.ref);
   158|    if (!c.goal || typeof c.goal !== 'string') throw new Error(`child.goal is required for ${c.ref}.`);
   159|  }
   160|  for (const c of specs) {
   161|    for (const dep of c.dependsOn ?? []) {
   162|      if (!refs.has(dep)) throw new Error(`child ${c.ref} depends on unknown ref: ${dep}`);
   163|      if (dep === c.ref) throw new Error(`child ${c.ref} cannot depend on itself.`);
   164|    }
   165|  }
