   168|// ---------- Child execution ----------
   169|
   170|function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
   171|  return new Promise<T>((resolve, reject) => {
   172|    const timer = setTimeout(() => reject(new Error(`child timed out after ${ms}ms`)), ms);
   173|    p.then((v) => { clearTimeout(timer); resolve(v); })
   174|     .catch((e) => { clearTimeout(timer); reject(e instanceof Error ? e : new Error(String(e))); });
   175|  });
