   188|
   189|  let dispatched: ReturnType<typeof dispatchTask>;
   190|  try {
   191|    dispatched = dispatchTask({
   192|      goal: spec.goal,
   193|      approverEmail,
   194|      forceAgent: spec.forceAgent,
   195|      metadata: { parentId, ref: spec.ref },
   196|    });
   197|  } catch (error) {
   198|    const msg = error instanceof Error ? error.message : 'dispatch failed';
   199|    recordAudit(cto, 'parent.child.dispatch_failed', `parent=${parentId} ref=${spec.ref} err=${msg}`, null, { parentId });
   200|    return {
   201|      ref: spec.ref,
   202|      taskId: null,
   203|      agentId: spec.forceAgent ?? routeTaskToAgent(spec.goal),
   204|      status: 'failed',
   205|      risk: classifyTaskRisk(spec.goal),
   206|      goal: spec.goal,
   207|      blockedReason: null,
   208|      error: msg,
   209|      result: null,
   210|      dependsOn,
   211|      startedAt,
   212|      finishedAt: nowIso(),
   213|      attempts: 0,
   214|      retries: maxRetries,
   215|      timedOut: false,
   216|    };
   217|  }
   218|
   219|  const t = dispatched.task;
   220|  recordAudit(cto, 'parent.child.spawned', `parent=${parentId} ref=${spec.ref} agent=${t.assignedAgent} risk=${t.risk}`, t.id, { parentId, ref: spec.ref });
