   222|  if (t.status === 'blocked') {
   223|    return {
   224|      ref: spec.ref,
   225|      taskId: t.id,
   226|      agentId: t.assignedAgent,
   227|      status: 'blocked',
   228|      risk: t.risk,
   229|      goal: spec.goal,
   230|      blockedReason: t.blockedReason,
   231|      error: null,
   232|      result: null,
   233|      dependsOn,
   234|      startedAt,
   235|      finishedAt: nowIso(),
   236|      attempts: 0,
   237|      retries: maxRetries,
   238|      timedOut: false,
   239|    };
   240|  }
   241|
   242|  let attempts = 0;
   243|  let lastError: string | null = null;
   244|  let timedOut = false;
   245|  let remainingFailures = Math.max(0, spec.__failTimes ?? 0);
