   248|    attempts += 1;
   249|    try {
   250|      await withTimeout((async () => {
   251|        if (spec.__simulateFailure) {
   252|          throw new Error('simulated child failure (isolation test)');
   253|        }
   254|        if (remainingFailures > 0) {
   255|          remainingFailures -= 1;
   256|          throw new Error(`transient failure (retry probe, remaining=${remainingFailures})`);
   257|        }
   258|      })(), timeoutMs);
   259|
   260|      // Safe action: namespaced memory proposal — no file or schema mutation.
   261|      const proposal = `[parallel] parent=${parentId} ref=${spec.ref} goal=${spec.goal.slice(0, 200)} attempts=${attempts}`;
   262|      writeAgentMemory(t.assignedAgent, `parallel:${parentId}:${spec.ref}`, proposal, {
   263|        parentId,
   264|        ref: spec.ref,
   265|        taskId: t.id,
   266|        attempts,
   267|        marker: PARALLEL_EXECUTION_MARKER,
   268|      });
   269|
   270|      const completed = completeTask(t.id, {
   271|        parentId,
   272|        ref: spec.ref,
   273|        block: 'block27-parallel-execution',
   274|        attempts,
   275|        marker: PARALLEL_EXECUTION_MARKER,
   276|      });
   277|
   278|      if (attempts > 1) {
   279|        recordAudit(cto, 'parent.child.retry_succeeded', `parent=${parentId} ref=${spec.ref} attempts=${attempts}`, t.id, { parentId, ref: spec.ref });
   280|      }
   281|
   282|      return {
   283|        ref: spec.ref,
   284|        taskId: t.id,
   285|        agentId: t.assignedAgent,
   286|        status: completed.status,
   287|        risk: t.risk,
   288|        goal: spec.goal,
   289|        blockedReason: null,
   290|        error: null,
   291|        result: completed.result,
   292|        dependsOn,
   293|        startedAt,
   294|        finishedAt: nowIso(),
   295|        attempts,
   296|        retries: maxRetries,
   297|        timedOut: false,
