   330|// ---------- Parent dispatch ----------
   331|
   332|export async function dispatchParallelTask(opts: ParallelDispatchOptions): Promise<ParentTaskRecord> {
   333|  const goal = opts.goal.trim();
   334|  if (!goal) throw new Error('goal is required.');
   335|
   336|  const specs = (opts.children && opts.children.length > 0) ? opts.children : autoDecomposeGoal(goal);
   337|  validateChildSpecs(specs);
   338|
   339|  const cto: AgentId = 'cto_orchestrator';
   340|  const parentId = uid('parent');
   341|  const auditEntries: AgentAuditEntry[] = [];
   342|
   343|  auditEntries.push(recordAudit(
   344|    cto,
   345|    'parent.received',
   346|    `goal="${goal.slice(0, 120)}" children=${specs.length}`,
   347|    null,
   348|    { parentId, marker: PARALLEL_EXECUTION_MARKER },
   349|  ));
   350|
   351|  // Pre-route audit so we can prove correct routing prior to execution.
   352|  for (const c of specs) {
   353|    const target = c.forceAgent ?? routeTaskToAgent(c.goal);
   354|    const risk = classifyTaskRisk(c.goal);
   355|    const policy = isActionAllowed(target, risk);
   356|    auditEntries.push(recordAudit(
   357|      cto,
   358|      'parent.child.planned',
   359|      `parent=${parentId} ref=${c.ref} agent=${target} risk=${risk} allowed=${policy.allowed}`,
   360|      null,
   361|      { parentId, ref: c.ref },
   362|    ));
   363|    recordHandoff(cto, target, parentId, `parallel split ref=${c.ref}`);
   364|  }
   365|
   366|  const parent: ParentTaskRecord = {
   367|    id: parentId,
   368|    goal,
   369|    status: 'running',
   370|    approverEmail: opts.approverEmail ?? null,
   371|    children: [],
   372|    aggregation: null,
   373|    audit: auditEntries,
   374|    createdAt: nowIso(),
   375|    updatedAt: nowIso(),
   376|    completedAt: null,
   377|  };
   378|  parents.set(parentId, parent);
   379|  trimStore();
   380|
   381|  const results = new Map<string, ChildTaskResult>();
   382|  const completedRefs = new Set<string>();
   383|  const allRefs = new Set(specs.map((s) => s.ref));
   384|
   385|  // Run by dependency layers; isolate failures so siblings continue.
   386|  let safety = 0;
   387|  while (completedRefs.size < specs.length) {
   388|    safety += 1;
   389|    if (safety > specs.length + 2) break;
   390|
   391|    const ready: ChildTaskSpec[] = [];
   392|    const skip: ChildTaskSpec[] = [];
   393|
   394|    for (const c of specs) {
   395|      if (completedRefs.has(c.ref)) continue;
   396|      const deps = c.dependsOn ?? [];
   397|      const depResults = deps.map((d) => results.get(d));
   398|      const anyDepBad = depResults.some((r) => r && (r.status === 'failed' || r.status === 'blocked' || r.status === 'skipped'));
   399|      const allDepOk = deps.every((d) => completedRefs.has(d));
   400|      if (anyDepBad) {
   401|        skip.push(c);
   402|      } else if (allDepOk) {
   403|        ready.push(c);
   404|      }
   405|    }
   406|
   407|    for (const s of skip) {
   408|      const target = s.forceAgent ?? routeTaskToAgent(s.goal);
   409|      const cr: ChildTaskResult = {
   410|        ref: s.ref,
   411|        taskId: null,
   412|        agentId: target,
   413|        status: 'skipped',
   414|        risk: classifyTaskRisk(s.goal),
   415|        goal: s.goal,
   416|        blockedReason: 'dependency failed/blocked',
   417|        error: null,
   418|        result: null,
   419|        dependsOn: s.dependsOn ?? [],
   420|        startedAt: null,
   421|        finishedAt: nowIso(),
   422|        attempts: 0,
   423|        retries: 0,
   424|        timedOut: false,
   425|      };
   426|      results.set(s.ref, cr);
   427|      completedRefs.add(s.ref);
   428|      auditEntries.push(recordAudit(cto, 'parent.child.skipped', `parent=${parentId} ref=${s.ref} reason=dep-failed`, null, { parentId }));
   429|    }
   430|
   431|    if (ready.length === 0) {
   432|      if (skip.length === 0) break; // stuck; should be unreachable
   433|      continue;
   434|    }
   435|
   436|    const settled = await Promise.allSettled(
   437|      ready.map((c) => executeChild(parentId, c, opts.approverEmail)),
   438|    );
   439|    settled.forEach((res, idx) => {
   440|      const spec = ready[idx]!;
   441|      if (res.status === 'fulfilled') {
   442|        results.set(spec.ref, res.value);
   443|      } else {
   444|        const msg = res.reason instanceof Error ? res.reason.message : 'parallel child rejected';
   445|        results.set(spec.ref, {
   446|          ref: spec.ref,
   447|          taskId: null,
   448|          agentId: spec.forceAgent ?? routeTaskToAgent(spec.goal),
   449|          status: 'failed',
   450|          risk: classifyTaskRisk(spec.goal),
   451|          goal: spec.goal,
   452|          blockedReason: null,
   453|          error: msg,
   454|          result: null,
   455|          dependsOn: spec.dependsOn ?? [],
   456|          startedAt: null,
   457|          finishedAt: nowIso(),
   458|          attempts: 0,
   459|          retries: 0,
   460|          timedOut: false,
   461|        });
   462|      }
   463|      completedRefs.add(spec.ref);
   464|    });
   465|  }
   466|
   467|  parent.children = specs.map((s) => results.get(s.ref) ?? {
   468|    ref: s.ref,
   469|    taskId: null,
   470|    agentId: s.forceAgent ?? routeTaskToAgent(s.goal),
   471|    status: 'failed',
   472|    risk: classifyTaskRisk(s.goal),
   473|    goal: s.goal,
   474|    blockedReason: null,
   475|    error: 'child never executed',
   476|    result: null,
   477|    dependsOn: s.dependsOn ?? [],
   478|    startedAt: null,
   479|    finishedAt: nowIso(),
   480|    attempts: 0,
   481|    retries: 0,
   482|    timedOut: false,
   483|  });
   484|
   485|  // Aggregation by CTO.
   486|  const successCount = parent.children.filter((c) => c.status === 'completed').length;
   487|  const failCount = parent.children.filter((c) => c.status === 'failed').length;
   488|  const blockedCount = parent.children.filter((c) => c.status === 'blocked').length;
   489|  const skippedCount = parent.children.filter((c) => c.status === 'skipped').length;
   490|  const agentsUsed = Array.from(new Set(parent.children.map((c) => c.agentId))) as AgentId[];
   491|
   492|  const summary = `parent=${parentId} children=${parent.children.length} success=${successCount} blocked=${blockedCount} failed=${failCount} skipped=${skippedCount} agents=[${agentsUsed.join(',')}]`;
   493|  parent.aggregation = {
   494|    summary,
   495|    successCount,
   496|    failCount,
   497|    blockedCount,
   498|    skippedCount,
   499|    agentsUsed,
   500|    at: nowIso(),
   501|  };
   502|
   503|  if (failCount === 0 && blockedCount === 0 && skippedCount === 0) {
   504|    parent.status = 'completed';
   505|  } else if (successCount === 0) {
   506|    parent.status = 'failed';
   507|  } else {
   508|    parent.status = 'partial';
   509|  }
   510|  parent.updatedAt = nowIso();
   511|  parent.completedAt = parent.updatedAt;
   512|
   513|  auditEntries.push(recordAudit(cto, 'parent.aggregated', summary, null, {
   514|    parentId,
   515|    successCount,
   516|    failCount,
   517|    blockedCount,
   518|    skippedCount,
   519|    marker: PARALLEL_EXECUTION_MARKER,
   520|  }));
   521|
   522|  // Persist a CTO memory entry summarizing the parent task.
   523|  writeAgentMemory('cto_orchestrator', `parallel:${parentId}:summary`, summary, {
   524|    parentId,
   525|    marker: PARALLEL_EXECUTION_MARKER,
   526|  });
   527|
   528|  return parent;
   529|}
