   266|function simulateValidation(kind: IssueKind): { ok: boolean; checks: Array<{ name: string; ok: boolean; detail: string }> } {
   267|  const checks: Array<{ name: string; ok: boolean; detail: string }> = [
   268|    { name: 'syntax', ok: true, detail: 'patch is syntactically valid (proposed)' },
   269|    { name: 'tsc',    ok: kind !== 'lint_type_issue', detail: kind === 'lint_type_issue' ? 'tsc still flags after partial fix' : 'tsc clean' },
   270|    { name: 'lint',   ok: true, detail: 'eslint clean (proposed)' },
   271|    { name: 'unit',   ok: kind !== 'broken_endpoint', detail: kind === 'broken_endpoint' ? 'integration test still red — needs second pass' : 'unit tests green' },
   272|  ];
   273|  // For broken_endpoint and lint_type_issue we deliberately surface a partial
   274|  // failure so the cycle can produce a rollback proposal instead of auto-deploy.
   275|  // For other kinds, validation is green and the low-risk gate can pass.
   276|  const ok = checks.every((c) => c.ok);
   277|  return { ok, checks };
