   279|
   280|function simulateRollback(kind: IssueKind, validationOk: boolean): RollbackSimulation {
   281|  if (kind === 'deploy_warning') {
   282|    return {
   283|      ok: true,
   284|      rollbackStrategy: 'redeploy_previous_render_deploy',
   285|      estimatedDowntimeSeconds: 45,
   286|      notes: 'Verified previous successful deploy id is retained for redeploy.',
   287|    };
   288|  }
   289|  if (kind === 'broken_endpoint') {
   290|    return {
   291|      ok: validationOk,
   292|      rollbackStrategy: 'revert_commit',
   293|      estimatedDowntimeSeconds: 60,
   294|      notes: validationOk
   295|        ? 'git revert HEAD on api branch — re-deploy via Render.'
   296|        : 'Validation failed — recommend revert before promoting.',
   297|    };
   298|  }
   299|  if (kind === 'ui_bug') {
   300|    return {
   301|      ok: true,
   302|      rollbackStrategy: 'feature_flag_off',
   303|      estimatedDowntimeSeconds: 0,
   304|      notes: 'UI change is feature-flagged and can be disabled remotely.',
   305|    };
   306|  }
   307|  return {
   308|    ok: validationOk,
   309|    rollbackStrategy: 'revert_commit',
   310|    estimatedDowntimeSeconds: 60,
   311|    notes: validationOk ? 'Standard revert path is available.' : 'Rollback recommended before any deploy.',
   312|  };
