   325|  if (!validationOk || !rollback.ok) {
   326|    action = 'blocked';
   327|    reasons.push('Validation or rollback simulation did not pass; deploy blocked.');
   328|  } else if (taskRisk === 'high') {
   329|    action = 'blocked';
   330|    reasons.push('High-risk task — automatic deploy is blocked.');
   331|  } else if (taskRisk === 'medium') {
   332|    action = ownerApproved ? 'auto_approved' : 'requires_owner_approval';
   333|    reasons.push(ownerApproved ? 'Medium-risk approved by owner.' : 'Medium-risk requires owner approval.');
   334|  } else if (classification.confidence === 'low') {
