   338|    action = 'auto_approved';
   339|    reasons.push('Low-risk + green validation + healthy rollback path.');
   340|  }
   341|
   342|  return {
   343|    riskLevel: taskRisk,
   344|    action,
   345|    reasons,
   346|    rollback,
   347|    proposedAt: nowIso(),
