   361|export async function runAutonomousCycle(opts: RunCycleOptions): Promise<CycleRecord> {
   362|  const cto: AgentId = 'cto_orchestrator';
   363|  const id = uid('cycle');
   364|  const cycle: CycleRecord = {
   365|    id,
   366|    signal: opts.signal,
   367|    classification: classifyIssue(opts.signal),
   368|    task: null,
   369|    incident: null,
   370|    patch: null,
   371|    validation: null,
   372|    rollback: null,
   373|    deploy: null,
   374|    approval: {
   375|      status: 'pending_owner_approval',
   376|      approvedBy: null,
   377|      approvedAt: null,
   378|      rejectedBy: null,
   379|      rejectedAt: null,
   380|      reason: null,
   381|    },
   382|    status: 'detected',
   383|    error: null,
   384|    steps: [],
   385|    createdAt: nowIso(),
   386|    updatedAt: nowIso(),
   387|  };
   388|  cycles.set(id, cycle);
   389|  trim();
   390|
   391|  pushStep(cycle, 'detected', `signal="${opts.signal.description.slice(0, 120)}"`);
   392|  recordAudit(cto, 'cycle.detected', `cycle=${id} kind=${cycle.classification.kind}`, null, { cycleId: id, marker: AUTONOMOUS_CYCLE_MARKER });
   393|
   394|  // Persist incident in operational memory (best-effort — never fail the cycle).
   395|  try {
   396|    cycle.incident = await recordEngIncident({
   397|      area: cycle.classification.area,
   398|      title: `Autonomous cycle: ${cycle.classification.kind}`,
   399|      summary: opts.signal.description.slice(0, 400),
   400|      signals: { ...opts.signal.metadata, cycleId: id, kind: cycle.classification.kind },
   401|    });
   402|  } catch (error) {
   403|    // Memory backend may be offline in dev — keep the cycle running.
   404|    recordAudit(cto, 'cycle.incident.persist_failed', error instanceof Error ? error.message : 'unknown', null, { cycleId: id });
   405|  }
   406|
   407|  pushStep(cycle, 'classified', `kind=${cycle.classification.kind} confidence=${cycle.classification.confidence}`);
   408|
   409|  // Route via CTO orchestrator using the multi-agent framework.
   410|  const dispatched = dispatchTask({
   411|    goal: `[autonomous] ${cycle.classification.kind}: ${opts.signal.description}`.slice(0, 600),
   412|    forceAgent: cycle.classification.preferredAgent,
   413|    approverEmail: opts.approverEmail,
   414|    metadata: { cycleId: id, marker: AUTONOMOUS_CYCLE_MARKER },
   415|  });
   416|  cycle.task = dispatched.task;
   417|  pushStep(cycle, 'routed', `agent=${dispatched.task.assignedAgent} risk=${dispatched.task.risk} status=${dispatched.task.status}`);
   418|
   419|  // If the framework blocked the task (high-risk without approval) we stop here.
   420|  if (dispatched.task.status === 'blocked') {
   421|    cycle.status = 'blocked';
   422|    cycle.approval.status = 'blocked';
   423|    cycle.error = dispatched.task.blockedReason;
   424|    recordAudit(dispatched.task.assignedAgent, 'cycle.blocked', dispatched.task.blockedReason ?? 'risk-gated', dispatched.task.id, { cycleId: id });
   425|    try {
   426|      await recordDecision({
   427|        kind: 'gate',
   428|        title: `cycle:${id}:blocked`,
   429|        reason: dispatched.task.blockedReason ?? 'risk-gated',
   430|        outcome: 'blocked',
   431|        metadata: { cycleId: id, kind: cycle.classification.kind },
   432|      });
   433|    } catch { /* non-fatal */ }
   434|    return cycle;
   435|  }
   436|
   437|  // Specialist agent: build patch proposal.
   438|  const patch = buildPatchProposal(cycle.classification.kind, opts.signal);
   439|  cycle.patch = patch;
   440|  writeAgentMemory(dispatched.task.assignedAgent, `cycle:${id}:patch`, JSON.stringify(patch).slice(0, 3500), {
   441|    cycleId: id,
   442|    kind: cycle.classification.kind,
   443|    marker: AUTONOMOUS_CYCLE_MARKER,
   444|  });
   445|  pushStep(cycle, 'patched', `file=${patch.filePath ?? 'n/a'} summary="${patch.summary.slice(0, 80)}"`);
   446|
   447|  // Validation — optionally forced to fail by callers exercising rollback.
   448|  const validation = opts.__forceValidationFailure
   449|    ? { ok: false, checks: [{ name: 'forced', ok: false, detail: 'forced failure for rollback validation' }] }
   450|    : simulateValidation(cycle.classification.kind);
   451|  cycle.validation = validation;
   452|  pushStep(cycle, 'validated', `ok=${validation.ok} checks=${validation.checks.length}`);
   453|
   454|  // Always simulate rollback BEFORE proposing deploy.
   455|  const rollback = simulateRollback(cycle.classification.kind, validation.ok);
   456|  cycle.rollback = rollback;
   457|  pushStep(cycle, 'rollback_simulated', `strategy=${rollback.rollbackStrategy} ok=${rollback.ok}`);
   458|
   459|  // Build deploy proposal under risk + confidence + approval policy.
   460|  const taskRisk = dispatched.task.risk;
   461|  const policy = isActionAllowed(dispatched.task.assignedAgent, taskRisk);
   462|  const ownerApproved = Boolean(dispatched.task.approvedBy) || (policy.allowed && taskRisk !== 'high' && Boolean(opts.approverEmail));
   463|  const deploy = buildDeployProposal(cycle.classification, validation.ok, rollback, taskRisk, ownerApproved);
   464|  cycle.deploy = deploy;
   465|  cycle.approval.status = deploy.action === 'auto_approved'
   466|    ? 'auto_approved'
   467|    : deploy.action === 'blocked'
   468|      ? 'blocked'
   469|      : 'pending_owner_approval';
   470|  pushStep(cycle, 'deploy_proposed', `action=${deploy.action} risk=${deploy.riskLevel}`);
   471|
   472|  // Persist a decision + fix outcome.
   473|  try {
   474|    await recordDecision({
   475|      kind: deploy.action === 'auto_approved' ? 'deploy' : deploy.action === 'blocked' ? 'gate' : 'patch',
   476|      title: `cycle:${id}:${deploy.action}`,
   477|      reason: deploy.reasons.join(' '),
   478|      outcome: deploy.action === 'auto_approved' ? 'success' : deploy.action === 'blocked' ? 'blocked' : 'pending',
   479|      metadata: { cycleId: id, kind: cycle.classification.kind, riskLevel: deploy.riskLevel, marker: AUTONOMOUS_CYCLE_MARKER },
   480|    });
   481|    await recordFixOutcome({
   482|      taskId: dispatched.task.id,
   483|      outcome: validation.ok ? (deploy.action === 'blocked' ? 'partial' : 'success') : 'rolled_back',
   484|      area: cycle.classification.area,
   485|      summary: `cycle ${id} ${cycle.classification.kind}: validation=${validation.ok} deploy=${deploy.action}`,
   486|    });
   487|  } catch (error) {
   488|    recordAudit(dispatched.task.assignedAgent, 'cycle.memory.persist_failed', error instanceof Error ? error.message : 'unknown', dispatched.task.id, { cycleId: id });
   489|  }
   490|
   491|  // Finalize task in framework.
   492|  if (validation.ok && deploy.action !== 'blocked') {
   493|    try {
   494|      completeTask(dispatched.task.id, {
   495|        cycleId: id,
   496|        kind: cycle.classification.kind,
   497|        deployAction: deploy.action,
   498|        marker: AUTONOMOUS_CYCLE_MARKER,
   499|      });
   500|    } catch { /* ignore */ }
   501|    cycle.status = 'completed';
   502|  } else {
   503|    try {
   504|      failTask(dispatched.task.id, deploy.reasons.join(' ').slice(0, 400) || 'validation failed');
   505|    } catch { /* ignore */ }
   506|    cycle.status = validation.ok ? 'blocked' : 'failed';
   507|    cycle.error = deploy.reasons.join(' ');
   508|  }
   509|
   510|  cycle.updatedAt = nowIso();
   511|  return cycle;
   512|}
