   682|    signal: { description: 'Outdated dependency detected: package version drift' },
   683|  });
   684|  ran.push(c1);
   685|  checks.push({
   686|    name: 'route.stale_dependency',
   687|    ok: c1.classification.kind === 'stale_dependency' && c1.task?.assignedAgent === 'infrastructure_sre',
   688|    detail: `kind=${c1.classification.kind} agent=${c1.task?.assignedAgent}`,
   689|  });
   690|  checks.push({
   691|    name: 'cycle1.completed',
   692|    ok: c1.status === 'completed' && c1.deploy?.action === 'auto_approved',
   693|    detail: `status=${c1.status} deploy=${c1.deploy?.action}`,
   694|  });
   695|
   696|  // Issue #2: UI bug — should auto-approve, feature_flag rollback path.
   697|  const c2 = await runAutonomousCycle({
   698|    signal: { description: 'UI visual glitch on small screens in expo screen component', hintKind: 'ui_bug' },
   699|  });
   700|  ran.push(c2);
   701|  checks.push({
   702|    name: 'route.ui_bug',
   703|    ok: c2.classification.kind === 'ui_bug' && c2.task?.assignedAgent === 'frontend_developer',
   704|    detail: `kind=${c2.classification.kind} agent=${c2.task?.assignedAgent}`,
   705|  });
   706|  checks.push({
   707|    name: 'cycle2.rollback_simulated',
   708|    ok: c2.rollback?.rollbackStrategy === 'feature_flag_off',
   709|    detail: `strategy=${c2.rollback?.rollbackStrategy}`,
   710|  });
   711|
   712|  // Issue #3: forced validation failure — must produce rollback proposal.
   713|  const c3 = await runAutonomousCycle({
   714|    signal: { description: 'Lint and tsc errors regression in backend service' },
   715|    __forceValidationFailure: true,
   716|  });
   717|  ran.push(c3);
   718|  checks.push({
   719|    name: 'cycle3.failed_repair_rollback',
   720|    ok: c3.validation?.ok === false && c3.rollback !== null && c3.deploy?.action === 'blocked',
   721|    detail: `validation=${c3.validation?.ok} rollback=${c3.rollback?.rollbackStrategy} deploy=${c3.deploy?.action}`,
   722|  });
   723|
   724|  // Issue #4: HIGH-RISK action — must remain blocked without approval.
   725|  const c4 = await runAutonomousCycle({
   726|    signal: { description: 'DROP supabase production schema and migrate all rows to a new partition' },
   727|  });
   728|  ran.push(c4);
