   490|// ── Public API: run an executive agent ───────────────────────────────────────
   491|
   492|/**
   493| * Run ONE executive agent NOW against its real engine, persist the run to the
   494| * durable ledger, and wire the result into unified + enterprise memory.
   495| * Concurrency-guarded per agent. Never throws.
   496| */
   497|export async function runExecutiveAgent(
   498|  agentId: ExecutiveAgentId,
   499|  trigger: ExecutiveAgentRun['trigger'] = 'owner',
   500|): Promise<ExecutiveAgentRun> {
   501|  const ranAt = nowIso();
   502|  if (inFlight.has(agentId)) {
   503|    return {
   504|      id: createRunId(),
   505|      agentId,
   506|      ranAt,
   507|      durationMs: 0,
   508|      ok: false,
   509|      summary: 'Agent already running.',
   510|      evidence: [],
   511|      error: 'Agent run already in flight.',
   512|      trigger,
   513|    };
   514|  }
   515|  inFlight.add(agentId);
   516|  const start = Date.now();
   517|  let run: ExecutiveAgentRun;
   518|  try {
   519|    const result = await executeAgent(agentId);
   520|    run = {
   521|      id: createRunId(),
   522|      agentId,
   523|      ranAt,
   524|      durationMs: Date.now() - start,
   525|      ok: result.ok,
   526|      summary: result.summary,
   527|      evidence: result.evidence,
   528|      error: result.error ?? null,
   529|      trigger,
   530|    };
   531|  } catch (error) {
   532|    run = {
   533|      id: createRunId(),
   534|      agentId,
   535|      ranAt,
   536|      durationMs: Date.now() - start,
   537|      ok: false,
   538|      summary: `${EXECUTIVE_AGENTS[agentId].name} failed.`,
   539|      evidence: [],
   540|      error: error instanceof Error ? error.message : 'Agent execution failed.',
   541|      trigger,
   542|    };
   543|  } finally {
   544|    inFlight.delete(agentId);
   545|  }
   546|
   547|  await enqueueWrite(async () => {
   548|    const state = await getEnterpriseOsState();
   549|    const agent = state.agents[agentId];
   550|    state.agents[agentId] = {
   551|      ...agent,
   552|      lastRunAt: run.ranAt,
   553|      lastStatus: run.ok ? 'ok' : 'failed',
   554|      lastSummary: run.error ? `${run.summary} (${run.error})` : run.summary,
   555|      runCount: agent.runCount + 1,
   556|      failureCount: agent.failureCount + (run.ok ? 0 : 1),
   557|    };
   558|    state.recentRuns = [run, ...state.recentRuns].slice(0, MAX_RECENT_RUNS);
   559|    await writeState(state);
   560|  });
   561|  await appendRunLog({
   562|    type: 'agent_run',
   563|    runId: run.id,
   564|    agentId,
   565|    ok: run.ok,
   566|    durationMs: run.durationMs,
   567|    summary: run.summary,
   568|    trigger,
   569|    at: run.ranAt,
   570|  });
   571|  await rememberRun(run);
   572|  return run;
   573|}
